// Run the app's own decode + hash path in a real browser and write the hashes out.
//
// Usage: node browser.mjs --clips clips/manifest.json --out out/browser.json
//                        [--browsers chromium,firefox,webkit] [--fps 1] [--headed] [--photos]
//
// The page under test is page/index.html, which imports src/lib/fingerprintClient.ts unchanged -
// the same code the "Add original" panel runs. This file only builds that page, serves it over
// loopback, hands each clip to a real <input type="file">, and collects the result.
//
// Only synthetic clips generated by parity.py ever go in here. Nothing is uploaded anywhere.

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "vite";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PAGE_DIR = path.join(HERE, "page");
const DIST_DIR = path.join(PAGE_DIR, "dist");
const DEFAULT_BROWSERS = ["chromium"];
// A 10 s clip is one seek plus eight PDQ hashes per sampled second; slow machines need slack.
const CLIP_TIMEOUT_MS = 10 * 60 * 1000;

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".wasm": "application/wasm",
  ".map": "application/json; charset=utf-8",
};

function parseArgs(argv) {
  const args = {
    clips: "clips/manifest.json",
    out: "out/browser.json",
    browsers: DEFAULT_BROWSERS,
    fps: 1,
    headed: false,
    // Photo sets (issue #116, ADR 0053): each manifest entry is a set of images, not one clip.
    photos: false,
  };
  for (let i = 0; i < argv.length; i++) {
    const flag = argv[i];
    const value = argv[i + 1];
    if (flag === "--clips") args.clips = value, i++;
    else if (flag === "--out") args.out = value, i++;
    else if (flag === "--fps") args.fps = Number(value), i++;
    else if (flag === "--browsers") args.browsers = value.split(",").map((n) => n.trim()).filter(Boolean), i++;
    else if (flag === "--headed") args.headed = true;
    else if (flag === "--photos") args.photos = true;
    else throw new Error(`unknown argument ${flag}`);
  }
  if (!Number.isFinite(args.fps) || args.fps <= 0) throw new Error("--fps must be positive");
  return args;
}

/** Bundle the harness page. `configFile: false` keeps the app's vite.config.ts (CSP, proxy) out. */
async function buildPage() {
  await build({
    root: PAGE_DIR,
    base: "./",
    configFile: false,
    logLevel: "warn",
    // fingerprintClient.ts starts the hasher with `new Worker(..., { type: "module" })`.
    worker: { format: "es" },
    build: { outDir: DIST_DIR, emptyOutDir: true, target: "es2022", sourcemap: false },
  });
}

/** Static loopback server for the built page. No proxying, no outside hosts, no uploads. */
async function serve(directory) {
  const server = createServer(async (request, response) => {
    const requested = new URL(request.url, "http://127.0.0.1").pathname;
    const relative = requested === "/" ? "index.html" : requested.replace(/^\/+/, "");
    const file = path.join(directory, relative);
    // Refuse anything that escapes the build output.
    if (!file.startsWith(directory)) {
      response.writeHead(403).end("forbidden");
      return;
    }
    try {
      const body = await readFile(file);
      response.writeHead(200, { "content-type": MIME[path.extname(file)] ?? "application/octet-stream" });
      response.end(body);
    } catch {
      response.writeHead(404).end("not found");
    }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  return { url: `http://127.0.0.1:${port}/`, close: () => new Promise((done) => server.close(done)) };
}

async function hashClips(browserType, name, clips, origin, args) {
  const browser = await browserType.launch({ headless: !args.headed });
  const version = browser.version();
  const results = [];
  try {
    const context = await browser.newContext();
    const page = await context.newPage();
    page.setDefaultTimeout(CLIP_TIMEOUT_MS);
    const consoleErrors = [];
    page.on("console", (message) => {
      if (message.type() === "error") consoleErrors.push(message.text());
    });
    page.on("pageerror", (error) => consoleErrors.push(String(error)));
    for (const clip of clips) {
      consoleErrors.length = 0;
      await page.goto(origin, { waitUntil: "load" });
      await page.waitForFunction(() => window.marcelineParity !== undefined);
      // A set is several files into the same `multiple` input; a clip is one.
      await page.setInputFiles("#clip", args.photos ? clip.paths : clip.path);
      const started = Date.now();
      const result = args.photos
        ? await page.evaluate(() => window.marcelineParity.runPhotos())
        : await page.evaluate((fps) => window.marcelineParity.run(fps), args.fps);
      results.push({
        clip: clip.name,
        wall_ms: Date.now() - started,
        console_errors: [...consoleErrors],
        ...result,
      });
      process.stderr.write(
        `${name} ${clip.name}: ${result.ok ? `${result.fingerprint.frames.length} hash rows` : `FAILED ${result.error.name}: ${result.error.message}`}\n`,
      );
    }
    await context.close();
  } finally {
    await browser.close();
  }
  return { name, version, launched: true, error: null, results };
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const manifestPath = path.resolve(args.clips);
  if (!existsSync(manifestPath)) {
    throw new Error(`no clip manifest at ${manifestPath} - run parity.py, which generates the clips`);
  }
  const manifest = JSON.parse(await readFile(manifestPath, "utf8"));
  const base = path.dirname(manifestPath);
  const clips = manifest.clips.map((clip) => ({
    ...clip,
    // A photo set names its images in `files`; a clip names one `file`.
    ...(clip.files === undefined
      ? { path: path.resolve(base, clip.file) }
      : { paths: clip.files.map((file) => path.resolve(base, file)) }),
  }));

  process.stderr.write(`building the harness page (vite)\n`);
  await buildPage();
  const server = await serve(DIST_DIR);
  process.stderr.write(`serving ${DIST_DIR} on ${server.url}\n`);

  const playwright = await import("playwright");
  const browsers = [];
  try {
    for (const name of args.browsers) {
      const browserType = playwright[name];
      if (!browserType) throw new Error(`unknown browser ${name}`);
      try {
        browsers.push(await hashClips(browserType, name, clips, server.url, args));
      } catch (error) {
        // A browser that is not installed is reported, never silently skipped.
        process.stderr.write(`${name}: unavailable - ${error.message}\n`);
        browsers.push({ name, version: null, launched: false, error: String(error.message), results: [] });
      }
    }
  } finally {
    await server.close();
  }

  const document = {
    generated_at: new Date().toISOString(),
    kind: args.photos ? "photos" : "video",
    fps: args.fps,
    node: process.version,
    platform: `${process.platform} ${process.arch}`,
    browsers,
  };
  const { mkdir, writeFile } = await import("node:fs/promises");
  const outPath = path.resolve(args.out);
  await mkdir(path.dirname(outPath), { recursive: true });
  await writeFile(outPath, `${JSON.stringify(document, null, 2)}\n`);
  process.stderr.write(`wrote ${outPath}\n`);
}

main().catch((error) => {
  process.stderr.write(`${error.stack ?? error}\n`);
  process.exit(1);
});
